messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 10px;
            left: 10px;
            color: white;
            font-family: sans-serif;
            font-weight: bold;
            font-size: 20px;
            text-shadow: 1px 1px 2px black;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">Waiting for start...</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const RACE_DISTANCE = 200;
        const CAM_Z = 40;
        const CAM_Y = 5;
        const TRACK_WIDTH = 12;
        const LANE_WIDTH = TRACK_WIDTH / 3;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, CAM_Y, CAM_Z);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 0.6);
        scene.add(hemiLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(1000, 1000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Finish Line
        const finishLineGeo = new THREE.PlaneGeometry(10, 4);
        const finishLineMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.01, -RACE_DISTANCE);
        finishLine.receiveShadow = true;
        scene.add(finishLine);

        // Checkered pattern for finish line (simple visual aid)
        const checkerGeo = new THREE.PlaneGeometry(10, 4);
        const checkerMat = new THREE.MeshBasicMaterial({ 
            color: 0x000000, 
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.5
        });
        const checker = new THREE.Mesh(checkerGeo, checkerMat);
        checker.rotation.x = -Math.PI / 2;
        checker.position.set(0, 0.02, -RACE_DISTANCE);
        scene.add(checker);

        // Track Borders
        const borderGeo = new THREE.BoxGeometry(0.5, 0.5, 1000);
        const borderMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const leftBorder = new THREE.Mesh(borderGeo, borderMat);
        leftBorder.position.set(-TRACK_WIDTH/2 - 1, 0.25, 0);
        scene.add(leftBorder);
        const rightBorder = new THREE.Mesh(borderGeo, borderMat);
        rightBorder.position.set(TRACK_WIDTH/2 + 1, 0.25, 0);
        scene.add(rightBorder);

        // --- Car Factory ---
        function createCar(color, laneIndex) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2.5, 0.5, 4.5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.5;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(2, 0.6, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.1, -0.2);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1.1, z: 1.2 }, { x: 1.1, z: 1.2 }, // Rear
                { x: -1.1, z: -1.2 }, { x: 1.1, z: -1.2 } // Front
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Tail lights
            const lightGeo = new THREE.BoxGeometry(0.4, 0.2, 0.1);
            const lightMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
            const tl = new THREE.Mesh(lightGeo, lightMat);
            tl.position.set(-0.8, 0.6, 2.26);
            carGroup.add(tl);
            const tr = new THREE.Mesh(lightGeo, lightMat);
            tr.position.set(0.8, 0.6, 2.26);
            carGroup.add(tr);

            return carGroup;
        }

        // --- Race Logic ---
        const redCar = createCar(0xff0000, 1); // Lane 1 (Middle)
        const blueCar = createCar(0x0000ff, 0); // Lane 0 (Left)

        // Initial positions (Start line at Z = 0)
        // Lane 0: -4, Lane 1: 0, Lane 2: 4
        blueCar.position.set(-LANE_WIDTH, 0.5, 0);
        redCar.position.set(0, 0.5, 0);

        scene.add(blueCar);
        scene.add(redCar);

        let raceState = 'START'; // START, RACING, FINISHED
        let time = 0;
        const finishLineMesh = checker; // Use checker for collision detection
        let finishLineZ = finishLine.position.z;

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            // Camera Follow Logic
            // We want the camera to follow the cars, but since they start at Z=0 and go to Z=-200,
            // and we are at Z=40, we need to move the camera back as they go forward.
            // However, the prompt says "Camera keeps both cars in view".
            // A fixed camera angle works best for a "race view".
            // Let's keep camera fixed in Z but move the cars forward.

            if (raceState === 'START') {
                // Wait a bit then start
                if (time > 2000) {
                    raceState = 'RACING';
                    document.getElementById('info').innerText = "RACE START!";
                }
            } 
            else if (raceState === 'RACING') {
                // Blue car starts fast, slows down
                // Red car starts slow, accelerates

                // Blue Car Logic
                // Starts at 200 speed, drops to 100 speed
                const blueSpeed = THREE.MathUtils.lerp(200, 100, time / 5000);
                blueCar.position.z -= blueSpeed;

                // Red Car Logic
                // Starts at 100 speed, accelerates to 250 speed
                const redSpeed = THREE.MathUtils.lerp(100, 250, time / 5000);
                redCar.position.z -= redSpeed;

                // Simple suspension bounce
                blueCar.position.y = 0.5 + Math.sin(time * 0.05) * 0.05;
                redCar.position.y = 0.5 + Math.sin(time * 0.05 + 1) * 0.05;

                // Bank the camera slightly based on speed
                camera.position.z = CAM_Z + (redCar.position.z < -50 ? 5 : 0);
                camera.lookAt(0, 0, redCar.position.z - 10);

                // Check Win Condition
                if (redCar.position.z <= finishLineZ) {
                    raceState = 'FINISHED';
                    document.getElementById('info').innerText = "RED WINS! RESET...";
                    setTimeout(resetRace, 2000);
                }
            }

            renderer.render(scene, camera);
        }

        function resetRace() {
            blueCar.position.z = 0;
            redCar.position.z = 0;
            raceState = 'START';
            time = 0;
            document.getElementById('info').innerText = "Waiting for start...";
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
